from pathlib import Path
p=Path('/data/lapka-app/app.js'); lines=p.read_text().splitlines()
def replace(prefix,new):
    global lines
    for i,line in enumerate(lines):
        if line.startswith(prefix):
            lines[i]=new
            return
    raise ValueError('missing '+prefix)
replace('  function shell(content){', '''  function shell(content){const desktop=navItems.slice(0,4).map(x=>navButton(x)).join('')+`<div class="nav-label">Уход и сервисы</div>`+[['vet','✚','Чат с врачом'],['food','◉','Опасные продукты'],...moreItems].map(x=>navButton(x)).join('');const mobile=[navItems[0],navItems[1],navItems[2],navItems[3],['more','•••','Ещё']].map(x=>`<button class="${route===x[0]?'active':''}" data-route="${x[0]}" aria-label="${x[2]}"><span class="nav-icon">${x[1]}</span><span>${x[2]}</span></button>`).join('');return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">🐾</div><div><div class="brand-name">Лапка</div><div class="brand-sub">забота рядом</div></div></div><div class="nav-label">Пространство</div><nav class="side-nav">${desktop}</nav><div class="sidebar-bottom"><div class="privacy-mini"><strong>🔒 Личные данные</strong><p>Профили и записи хранятся локально в этом браузере.</p></div><div class="user-mini"><div class="avatar">🐾</div><div><div class="user-name">Мой профиль</div><div class="user-tag">Локальное хранение</div></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Лапка <span style="color:#c4cbc5"> / </span> ${esc(routeLabel())}</div><div class="top-actions"><span class="top-date">${fmtDate(today,{weekday:'short',day:'numeric',month:'long'})}</span>${state.pets.length?`<select class="top-pet-select" id="top-pet-select" aria-label="Выбрать питомца">${state.pets.map(p=>`<option value="${esc(p.id)}" ${p.id===currentPet()?.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:''}<button class="icon-button" data-route="settings" aria-label="Настройки">⚙</button></div></header><div class="content">${content}</div></main><nav class="mobile-nav" aria-label="Основная навигация">${mobile}</nav></div>`}''')
replace('  function demoBanner(', '''  function demoBanner(text='Локальное хранение: данные остаются в этом браузере. Для синхронизации между устройствами потребуется подключить сервер.'){return `<div class="demo-banner"><span>ⓘ</span><span>${text}</span></div>`}''')
replace('  function eventCard(', '''  function eventCard(e,compact=false){const p=petById(e.petId);return `<div class="event-row"><div class="event-date"><b>${dayNum(e.date)}</b><small>${fmtDate(e.date,{month:'short'})}</small></div><div class="event-info"><b>${esc(e.title)} ${e.done?'<span class="tag green">Готово</span>':''}</b><p>${esc(p?.name||'Питомец')} · ${esc(e.note||'Без заметки')}${e.repeatDays?` · повтор: ${e.repeatDays} дн.`:''}</p></div><div class="event-actions">${!e.done?`<button class="btn btn-soft btn-small" data-action="event-done" data-id="${e.id}" aria-label="Завершить">✓</button>`:''}<button class="btn btn-secondary btn-small" data-action="edit-event" data-id="${e.id}" aria-label="Изменить">⋯</button></div></div>`}''')
insert_after='  const currentPet=()=>petById(state.activePetId)||state.pets[0]||null;'
for i,line in enumerate(lines):
 if line==insert_after:
  lines.insert(i+1,'''  function petIcon(p,cls='pet-avatar'){if(!p)return `<div class="${cls} pet-photo-frame"><span class="pet-fallback">🐾</span></div>`;return `<div class="${cls} pet-photo-frame">${p.photoId?`<img data-local-file="${esc(p.photoId)}" alt="Фото питомца ${esc(p.name)}"><span class="pet-fallback">${esc(p.emoji||'🐾')}</span>`:`<span class="pet-fallback">${esc(p.emoji||'🐾')}</span>`}</div>`}''')
  break
else: raise ValueError('missing currentPet')
# Replace major route functions. Each is one source line, so source is not parsed or truncated.
replace('  function homePage(){', '''  function homePage(){const p=currentPet();const upcoming=p?state.events.filter(e=>e.petId===p.id&&!e.done).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3):[];return `${demoBanner()}<section class="hero"><div class="hero-copy"><div class="eyebrow">Ваше пространство заботы</div><h1>Всё важное<br>о вашем питомце 🐾</h1><p>Профиль, полезные заметки и ежедневный уход — собраны в одном спокойном месте.</p><button class="btn btn-primary" data-route="care">Открыть таймлайн <span>→</span></button></div>${p?`<div class="pet-switcher">${petIcon(p,'pet-emoji')}<div><small>Сейчас выбран</small><select id="hero-pet-select" aria-label="Выбрать питомца">${state.pets.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><button class="btn btn-quiet" data-route="pets" aria-label="Управлять питомцами">↗</button></div>`:`<button class="btn btn-primary" data-action="add-pet">＋ Добавить питомца</button>`}</section><div class="section-heading"><h2>Быстрые действия</h2><span class="tag">${p?`Для ${esc(p.name)}`:'Начните с профиля'}</span></div><div class="quick-grid">${quick('✚','tint-peach','Чат с врачом','Подготовить обращение','vet')}${quick('◉','tint-lav','Опасные продукты','Справочник с источниками','food')}${quick('⌖','tint-blue','Петфрендли места','Каталог мест','places')}${quick('♡','tint-mint','Профиль питомца','Фото и сведения','pets')}${quick('▤','tint-lime','База знаний','Полезные материалы','knowledge')}${quick('▣','tint-peach','Архив документов','Личные файлы','documents')}${quick('◷','tint-blue','Таймлайн','События и напоминания','care')}${quick('♧','tint-lav','Дневник питания','Записи о рационе','care')}${quick('▧','tint-pink','Галерея','Фотографии питомца','gallery')}${quick('✉','tint-lime','Полезные шаблоны','Чек-листы и заметки','templates')}${quick('☻','tint-mint','Сообщество','Без вымышленных профилей','community')}</div><div class="section-heading"><h2>Ближайшие события</h2><button data-route="care">Весь таймлайн →</button></div><div class="card"><div class="event-list">${upcoming.length?upcoming.map(e=>eventCard(e,true)).join(''):empty('◷','Пока нет событий',p?'Создайте напоминание для '+esc(p.name)+'.':'Сначала добавьте питомца, затем создайте напоминание.',p?`<button class="btn btn-primary btn-small" data-action="add-event">Создать событие</button>`:`<button class="btn btn-primary btn-small" data-action="add-pet">Добавить питомца</button>`)}</div></div><p class="footer-note">Приложение помогает вести записи, но не заменяет ветеринарную консультацию.</p>`}''')
replace('  function petsPage(){', '''  function petsPage(){return `${title('Профили','Мои питомцы','Создавайте личные карточки, добавляйте фото и переключайтесь между питомцами.',`<button class="btn btn-primary" data-action="add-pet">＋ Добавить питомца</button>`)}${demoBanner('Фотографии и сведения хранятся в текущем браузере. Они не публикуются автоматически.')}${state.pets.length?`<div class="pet-grid">${state.pets.map(p=>`<article class="card pet-card ${p.id===currentPet()?.id?'selected':''}">${petIcon(p,'pet-avatar')}<h3>${esc(p.name)} ${p.id===currentPet()?.id?'<span class="tag green">Выбран</span>':''}</h3><p>${esc(p.species||'Питомец')}${p.breed?` · ${esc(p.breed)}`:''}<br>${p.birthDate?`Дата рождения: ${fmtDate(p.birthDate,{day:'numeric',month:'long',year:'numeric'})}`:'Дата рождения не указана'}</p>${p.note?`<p>${esc(p.note)}</p>`:''}<div class="card-controls"><button class="btn btn-soft btn-small" data-action="select-pet" data-id="${p.id}">Выбрать</button><button class="btn btn-secondary btn-small" data-action="edit-pet" data-id="${p.id}">Изменить</button><button class="btn btn-quiet btn-small" data-action="delete-pet" data-id="${p.id}">Удалить</button></div></article>`).join('')}</div>`:empty('🐾','Профиль питомца появится здесь','Добавьте имя, вид, породу и любимое фото — всё останется приватным.',`<button class="btn btn-primary" data-action="add-pet">Создать профиль питомца</button>`)}`}''')
replace('  function foodPage(){', '''  function foodPage(){const count=(window.LAPKA_FOOD_CATALOG||[]).length;return `${title('Проверка продуктов','Можно ли собаке?','Ищите продукт по названию или ингредиенту. У каждой проверенной карточки есть объяснение и источник.')}${demoBanner(`В справочнике ${count} курируемых карточек. Для неизвестного продукта приложение не угадывает и не считает его безопасным.`)}<div class="card"><label class="label" for="food-search">Название продукта</label><form id="food-check-form" class="food-check"><input id="food-search" class="input" placeholder="Например, шоколад, морковь или ксилитол" autocomplete="off"/><button class="btn btn-primary">Найти</button></form><div id="food-result"></div><div class="notice">При возможном поедании опасного продукта, выраженных симптомах или сомнениях немедленно свяжитесь с ветеринарной клиникой. Не ждите ответа справочника и не вызывайте рвоту самостоятельно.</div></div><div class="section-heading"><h2>Справочник</h2><span class="tag">${count} карточек</span></div><div class="subnav food-filters"><button data-food-filter="all" class="${foodFilter==='all'?'active':''}">Все</button><button data-food-filter="danger" class="${foodFilter==='danger'?'active':''}">Опасно</button><button data-food-filter="caution" class="${foodFilter==='caution'?'active':''}">Осторожно</button><button data-food-filter="okay" class="${foodFilter==='okay'?'active':''}">Условно допустимо</button></div><div id="food-catalog-list" class="grid grid-2"></div><p class="footer-note">Справочник не является полной базой токсикологии. Оценка зависит от продукта, состава, количества, размера и здоровья собаки. Обсуждайте рацион с ветеринаром.</p>`}''')
replace('  function vetPage(){', '''  function vetPage(){return `${title('Подготовка к консультации','Чат с врачом','Опишите проблему по готовой форме и подготовьте ясное сообщение специалисту.')}${demoBanner('Чат с лицензированным врачом ещё не подключён. Черновик останется у вас и не будет отправлен автоматически.') }<div class="two-col"><section class="card"><div class="profile-hero"><div class="profile-art">🩺</div><div><span class="tag orange">Врач пока не подключён</span><h2 style="font-size:17px;margin-top:8px">Подготовьте обращение заранее</h2><p class="page-subtitle" style="margin-top:5px">Выберите тему и ответьте на вопросы — приложение соберёт короткую сводку для ветеринара.</p></div></div><div class="notice" style="background:#fff2ea;color:#875a3b"><b>Срочно:</b> при затруднённом дыхании, судорогах, потере сознания, сильном кровотечении или резком ухудшении немедленно обращайтесь в круглосуточную клинику. Не ждите ответа в приложении.</div><button class="btn btn-primary" style="margin-top:16px" data-action="open-vet-intake">Подготовить сообщение</button></section><aside class="card"><h2 style="font-size:14px">Что полезно сообщить врачу</h2><div class="grid" style="gap:9px;margin-top:13px"><div class="list-card"><span class="list-icon">1</span><div class="list-main"><b>Когда началось</b><p>Дата, время и изменение симптомов.</p></div></div><div class="list-card"><span class="list-icon">2</span><div class="list-main"><b>Что изменилось</b><p>Аппетит, вода, активность, стул.</p></div></div><div class="list-card"><span class="list-icon">3</span><div class="list-main"><b>Что мог съесть</b><p>Название, количество, время и упаковка.</p></div></div><div class="list-card"><span class="list-icon">4</span><div class="list-main"><b>Лекарства и диагнозы</b><p>Только факты, не назначайте лечение самостоятельно.</p></div></div></div></aside></div>`}''')
